// All prototype state lives in this tab only. Nothing is written to storage or sent to a service.
const app=document.querySelector('#app'),toastBox=document.querySelector('#toast');
const state={screen:'welcome',step:1,profile:{name:'',email:'',timezone:'Asia/Kolkata'},client:{name:'',email:'',phone:'',timezone:'Asia/Kolkata',currency:'INR',channel:'WhatsApp',limit:''},clients:[],tasks:[],messages:[],events:[],requests:[],view:'dashboard',role:'assistant',activeClient:'all',capture:{text:'',clientId:'',channel:'WhatsApp',taskTitle:'',due:'',priority:'Normal'},taskFilter:'all',modal:''};
const colors=['#8471c6','#d77c69','#42978d','#c99f42','#5883ca'];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(msg){toastBox.textContent=msg;toastBox.classList.add('show');clearTimeout(toastBox.timer);toastBox.timer=setTimeout(()=>toastBox.classList.remove('show'),2500)}
function initials(s){return (s||'').trim().split(/\s+/).slice(0,2).map(x=>x[0]?.toUpperCase()||'').join('')||'PA'}
function clientById(id){return state.clients.find(c=>c.id===id)}
function clientMark(id){const c=clientById(id);return `<i class="client-dot" style="background:${c?.color||'#8293ad'}"></i>`}
function wordmark(){return `<a class="wordmark" href="#" data-action="home"><span class="brand-glyph">f</span><span>fieldnote</span></a>`}
function render(){if(state.screen==='welcome')return renderWelcome();if(state.screen==='onboarding')return renderOnboarding();if(state.screen==='portal')return renderPortal();renderWorkspace()}
function renderWelcome(){app.innerHTML=`<section class="onboard"><div class="onboard-left">${wordmark()}<div class="welcome-kicker">A calmer way to run the details</div><h1 class="welcome-title">Make the busy parts feel <span>handled.</span></h1><p class="welcome-copy">One thoughtful workspace for the people, plans and little details you look after every day.</p><ul class="welcome-points"><li><span class="point-check">✓</span>Keep every client’s world clearly separate</li><li><span class="point-check">✓</span>Turn a conversation into a clear next step</li><li><span class="point-check">✓</span>See what needs you, what’s waiting and what’s done</li></ul><div class="privacy-line"><span class="privacy-lock">▣</span>Private by design. Your setup stays in this browser demo.</div></div><div><div class="onboard-card" data-step="1"><div class="step-top"><span class="step-label">A workspace made around your work</span><span class="step-count">About 2 minutes</span></div><h2>Start with the way you work.</h2><p class="card-description">We’ll guide you through a few simple steps. No integrations or real accounts needed for this preview.</p><div class="visual-side"><div class="visual-caption">Your day, with a little more clarity</div><div class="visual-title">From “I’ll remember that” to “already handled.”</div><div class="flow-preview"><div class="flow-node"><div class="flow-node-mark">✉</div><b>A message comes in</b><small>From a client, your way</small></div><div class="flow-arrow">›</div><div class="flow-node"><div class="flow-node-mark">☷</div><b>You choose the next step</b><small>Review before creating</small></div><div class="flow-arrow">›</div><div class="flow-node"><div class="flow-node-mark">✓</div><b>Nothing slips through</b><small>Clear, client by client</small></div></div><div class="privacy-promise"><span>▣</span><span><b>Your notes stay private.</b> Your client only sees what you choose to share.</span></div></div><button class="button button-primary button-full" data-action="start">Set up my workspace <span class="button-arrow">→</span></button><div class="form-foot"><span></span><button class="skip-link" data-action="explore">Explore the empty workspace</button></div><div class="secure-assurance"><span class="shield">✓</span> This demo stores nothing and uses no real connections.</div></div></div></section>`}
function stepHeader(title,desc){return `<div class="step-top"><span class="step-label">WORKSPACE SETUP</span><span class="step-count">Step ${state.step} of 4</span></div><h2>${title}</h2><p class="card-description">${desc}</p>`}
function stepFooter(next,skip=''){return `<div class="form-foot"><button class="button-text step-back" data-action="back">← Back</button>${skip?`<button class="button-text skip-link" data-action="skip-email">${skip}</button>`:'<span></span>'}<button class="button button-primary" data-action="${next}">${state.step===4?'Enter workspace':'Continue'} <span class="button-arrow">→</span></button></div>`}
function renderOnboarding(){const s=state.step;let body='';if(s===1){body=`${stepHeader('First, a little about you.','This helps us shape your workspace and keep dates in the right time zone.')}<div class="form-field"><label for="profileName">Your name <span class="optional">REQUIRED</span></label><input class="input" id="profileName" autocomplete="name" value="${esc(state.profile.name)}" placeholder="e.g. Alex Lee"></div><div class="form-field"><label for="profileEmail">Work email <span class="optional">OPTIONAL FOR THIS PREVIEW</span></label><input class="input" id="profileEmail" type="email" autocomplete="email" value="${esc(state.profile.email)}" placeholder="you@example.com"></div><div class="form-field"><label for="profileTimezone">Your time zone</label><select class="select" id="profileTimezone">${timezones(state.profile.timezone)}</select><p class="form-help">Used to display deadlines and appointments clearly.</p></div>${stepFooter('profile-next')}`}
else if(s===2){body=`${stepHeader('Who do you look after first?','Add one client to start. You can add others from your workspace any time.')}<div class="form-field"><label for="clientName">Client name <span class="optional">REQUIRED</span></label><input class="input" id="clientName" value="${esc(state.client.name)}" placeholder="e.g. Jordan Rivera"></div><div class="form-grid"><div class="form-field"><label for="clientEmail">Email <span class="optional">OPTIONAL</span></label><input class="input" id="clientEmail" type="email" value="${esc(state.client.email)}" placeholder="jordan@example.com"></div><div class="form-field"><label for="clientPhone">Phone <span class="optional">OPTIONAL</span></label><input class="input" id="clientPhone" type="tel" value="${esc(state.client.phone)}" placeholder="Phone number"></div></div><div class="form-grid"><div class="form-field"><label for="clientTimezone">Client time zone</label><select class="select" id="clientTimezone">${timezones(state.client.timezone)}</select></div><div class="form-field"><label for="clientCurrency">Currency</label><select class="select" id="clientCurrency">${[['INR','INR · ₹'],['USD','USD · $'],['GBP','GBP · £'],['EUR','EUR · €'],['CAD','CAD · $'],['AUD','AUD · $']].map(x=>`<option value="${x[0]}" ${x[0]===state.client.currency?'selected':''}>${x[1]}</option>`).join('')}</select></div></div><div class="form-grid"><div class="form-field"><label for="clientChannel">Preferred channel</label><select class="select" id="clientChannel">${['WhatsApp','iMessage','SMS','Email'].map(c=>`<option ${state.client.channel===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="form-field"><label for="clientLimit">Approval limit <span class="optional">OPTIONAL</span></label><input class="input" id="clientLimit" type="number" min="0" value="${esc(state.client.limit)}" placeholder="e.g. 250"></div></div><div class="soft-info"><b>Client privacy:</b> each client gets a separate workspace. Your private notes are never shown in the client view.</div>${stepFooter('client-next')}`}
else if(s===3){body=`${stepHeader('Keep shared email in view.','Connect an account in the real product to review email beside each client’s tasks. This preview only shows the consent step.')}<div class="review-card"><b>${esc(state.client.name||'Your client')}’s email</b><p>Choose a provider to see the permission request. No password is requested or stored. This preview will not contact a provider or connect an account.</p></div><div class="form-grid provider-grid"><button class="button button-secondary" data-action="provider" data-provider="Google">◉ &nbsp; Google</button><button class="button button-secondary" data-action="provider" data-provider="Microsoft">▦ &nbsp; Microsoft</button></div><div class="soft-info"><b>Secure by design.</b> The real product uses a provider consent screen and limited permissions. Never share an email password with an assistant tool.</div>${stepFooter('email-next','Skip for now')}`}
else {body=`${stepHeader('You’re ready to begin.','Your workspace has the basics in place. We’ll start with a clean slate and show each next step as you go.')}<div class="review-card"><b>Workspace summary</b><p>Assistant: ${esc(state.profile.name||'You')} · Time zone: ${esc(state.profile.timezone)}<br>First client: ${esc(state.client.name||'No client added')} · Preferred channel: ${esc(state.client.channel)}</p></div><div class="consent-list"><span>Your workspace starts empty; no example clients or tasks.</span><span>Anything you add in this preview stays in memory only.</span><span>Refresh the page and the demo resets.</span></div><button class="button button-primary button-full" data-action="enter-workspace">Open my workspace <span class="button-arrow">→</span></button><div class="form-foot"><button class="button-text step-back" data-action="back">← Back</button><span></span></div>`}
app.innerHTML=`<section class="onboard"><div class="onboard-left">${wordmark()}<div class="welcome-kicker">A calmer way to run the details</div><h1 class="welcome-title">Make the busy parts feel <span>handled.</span></h1><p class="welcome-copy">A few details now make your first day clearer. You’re always in control of what’s shared.</p><ul class="welcome-points"><li><span class="point-check">✓</span>Separate workspaces for every client</li><li><span class="point-check">✓</span>Messages become reviewed next steps</li><li><span class="point-check">✓</span>Private notes stay yours</li></ul><div class="privacy-line"><span class="privacy-lock">▣</span>Demo only. Nothing is saved outside this browser tab.</div></div><div class="onboard-card" data-step="${s}">${body}</div></section>`}
function timezones(value){const opts=[['Asia/Kolkata','India Standard Time (UTC+05:30)'],['America/New_York','Eastern Time'],['America/Chicago','Central Time'],['America/Denver','Mountain Time'],['America/Los_Angeles','Pacific Time'],['Europe/London','United Kingdom'],['Europe/Paris','Central European Time'],['Asia/Dubai','Gulf Standard Time'],['Asia/Singapore','Singapore Time'],['Australia/Sydney','Australian Eastern Time']];return opts.map(([v,l])=>`<option value="${v}" ${v===value?'selected':''}>${l}</option>`).join('')}
function enterWorkspace(){if(state.client.name.trim()&&!state.clients.length){const id=crypto.randomUUID();state.clients.push({...state.client,id,color:colors[0]});state.activeClient=id}state.screen='workspace';state.view='dashboard';render()}
function renderWorkspace(){const c=clientById(state.activeClient)||state.clients[0],clientName=c?.name||'No client selected',name=state.profile.name||'Assistant';const views={dashboard:['Today','A clear view of what needs you, what can wait, and what is already handled.'],inbox:['Inbox','Review conversations and turn them into thoughtful next steps.'],tasks:['Tasks','Keep requests moving, with a clear owner and status.'],calendar:['Calendar','Bring appointments and follow-ups together.'],clients:['Clients','A separate, organized space for every person you support.'],approvals:['Approvals','See decisions waiting on your client before you proceed.'],settings:['Settings','Manage workspace preferences and privacy.']};let [heading,sub]=views[state.view]||views.dashboard;
const navs=[['dashboard','▦','Overview'],['inbox','▤','Inbox'],['tasks','☷','Tasks'],['calendar','◷','Calendar'],['clients','♙','Clients'],['approvals','✓','Approvals']];
app.innerHTML=`<div class="app-frame"><header class="workflow-header"><a class="workflow-brand" href="#" data-action="home"><span class="brand-glyph">f</span>fieldnote</a><div class="demo-indicator"><i></i> Interactive preview · changes are temporary</div><div class="header-right"><select class="role-switch" id="roleSwitch" aria-label="Preview role"><option value="assistant">Assistant workspace</option><option value="client">Preview client portal</option><option value="employee">Preview employee portal</option></select><div class="user-pill"><span class="avatar">${esc(initials(name))}</span><span>${esc(name)}</span></div></div></header><div class="workspace-layout"><aside class="workspace-sidebar"><div class="workspace-name">ASSISTANT WORKSPACE</div><div class="client-context">${clientMark(c?.id||'')}<span>${esc(clientName)}</span><select class="client-context-select" id="clientSelect" aria-label="Select client"><option value="all">All clients</option>${state.clients.map(x=>`<option value="${x.id}" ${state.activeClient===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="side-nav-label">WORK</div><nav class="side-nav">${navs.map(([id,icon,label])=>`<button data-view="${id}" class="${state.view===id?'active':''}"><span class="nav-glyph">${icon}</span>${label}${id==='inbox'&&state.messages.length?`<span class="nav-badge">${state.messages.length}</span>`:''}</button>`).join('')}</nav><div class="side-divider"></div><div class="side-nav-label">PORTALS</div><nav class="side-nav"><button data-action="portal" data-role="client"><span class="nav-glyph">◉</span>Client view</button><button data-action="portal" data-role="employee"><span class="nav-glyph">♙</span>Employee view</button></nav><div class="sidebar-note"><b>Private by design</b>Your client’s view never includes your private notes or other clients’ information.</div></aside><main class="workspace-main"><div class="context-banner">${clientMark(c?.id||'')}<span>Working in: <b>${esc(clientName)}</b></span><span class="private-icon">▣ Private workspace</span></div><div class="main-heading"><div><div class="eyebrow">${state.view==='dashboard'?'YOUR WORKSPACE':'WORKSPACE'}</div><h1>${heading}${state.view==='dashboard'&&state.profile.name?`, ${esc(name)}`:''}</h1><p>${sub}</p></div><div class="heading-actions">${state.view==='dashboard'||state.view==='inbox'?'<button class="button button-secondary" data-action="capture">Capture message</button>':''}<button class="button button-primary" data-action="${state.view==='tasks'?'new-task':state.view==='clients'?'new-client':state.view==='calendar'?'new-event':'new-task'}"><span>＋</span> ${state.view==='clients'?'Add client':state.view==='calendar'?'Add event':'New task'}</button></div></div>${renderCurrentView()}<footer class="workspace-footer"><span><i class="privacy-bullet"></i>Demo workspace · nothing is sent or stored</span><span>Each client stays separate</span></footer></main></div><nav class="mobile-bottom"><button class="${state.view==='dashboard'?'active':''}" data-view="dashboard"><b>▦</b>Home</button><button class="${state.view==='inbox'?'active':''}" data-view="inbox"><b>▤</b>Inbox</button><button class="${state.view==='tasks'?'active':''}" data-view="tasks"><b>☷</b>Tasks</button><button class="${state.view==='calendar'?'active':''}" data-view="calendar"><b>◷</b>Calendar</button><button data-action="new-task"><b>＋</b>Create</button></nav></div>`}
function renderCurrentView(){switch(state.view){case'dashboard':return renderDashboard();case'inbox':return renderInbox();case'tasks':return renderTasks();case'calendar':return renderCalendar();case'clients':return renderClients();case'approvals':return `<section class="workflow-panel"><div class="panel-head"><h2>Approvals</h2><span>Waiting on a client decision</span></div><div class="table-empty"><div class="empty-mini-icon">✓</div>No requests are waiting for approval.<br>Ask for approval before committing to a purchase or booking.</div></section>`;case'settings':return `<section class="workflow-panel"><div class="panel-head"><h2>Privacy and preferences</h2><span>Preview controls</span></div><div class="task-item"><div class="task-item-main"><b>Data storage</b><small>This prototype keeps additions in memory for this tab only.</small></div><span class="task-status done">Off</span></div><div class="task-item"><div class="task-item-main"><b>External connections</b><small>No accounts are connected from this preview.</small></div><span class="task-status">Not connected</span></div></section>`}}
function renderDashboard(){const work=state.tasks.filter(t=>state.activeClient==='all'||t.clientId===state.activeClient),done=work.filter(t=>t.status==='Completed').length,waiting=work.filter(t=>t.status==='Waiting for Client').length;return `<div class="metric-row"><div class="metric"><div class="metric-label">Clients</div><div class="metric-value">${state.clients.length}</div><div class="metric-foot">In your workspace</div></div><div class="metric"><div class="metric-label">Open tasks</div><div class="metric-value">${work.length-done}</div><div class="metric-foot">Only what you add</div></div><div class="metric"><div class="metric-label">Waiting on</div><div class="metric-value">${waiting}</div><div class="metric-foot">Client decisions</div></div><div class="metric"><div class="metric-label">Messages captured</div><div class="metric-value">${state.messages.length}</div><div class="metric-foot">Reviewed by you</div></div></div><section class="empty-hero"><div class="empty-hero-copy"><div class="empty-hero-kicker">A FRESH START</div><h2>${work.length?'Your day is taking shape.':'Your workspace starts with you.'}</h2><p>${work.length?'Each message, task and appointment you add will appear here. Keep the next step visible and the details close at hand.':'There are no sample clients, tasks or conversations here. Add your first client, then capture a message and turn it into a task when you are ready.'}</p><button class="button button-primary" data-action="${state.clients.length?'capture':'new-client'}">${state.clients.length?'Capture your first message':'Add your first client'} <span class="button-arrow">→</span></button></div><div class="empty-art"><span class="floating-chip one">One client at a time</span><span class="floating-chip two">Private notes stay yours</span><div class="empty-art-center">f</div></div></section><div class="empty-callout"><span class="callout-icon">✓</span><span><strong>Nothing here is prefilled.</strong> Use your own example details to walk through the flow. Refreshing clears everything.</span></div><h2 class="section-title">How the work moves</h2><div class="workflow-cards"><article class="workflow-card"><span class="step-number">1</span><b>Capture a conversation</b><p>Choose a client, channel and message.</p></article><article class="workflow-card"><span class="step-number">2</span><b>Review the next step</b><p>Edit a task before it enters your list.</p></article><article class="workflow-card"><span class="step-number">3</span><b>Keep it moving</b><p>Update status as you act or wait.</p></article></div>${work.length?`<h2 class="section-title">Your tasks</h2>${renderTaskPanel(work.slice(0,5))}`:''}`}
function renderTaskPanel(list){return `<section class="workflow-panel"><div class="panel-head"><h2>Tasks</h2><span>${list.length} added in this preview</span></div>${list.length?list.map(taskRow).join(''):`<div class="table-empty"><div class="empty-mini-icon">☷</div>No tasks yet. Capture a message or add a task to begin.</div>`}</section>`}
function taskRow(t){return `<div class="task-item"><span class="task-item-main"><b>${esc(t.title)}</b><small>${clientMark(t.clientId)} ${esc(clientById(t.clientId)?.name||'Client')} · ${esc(t.due||'No due date')} · ${esc(t.priority)}</small></span><select aria-label="Update status for ${esc(t.title)}" data-task-status="${t.id}">${['New Request','In Progress','Waiting for Client','Waiting for Approval','Scheduled','Completed'].map(s=>`<option ${t.status===s?'selected':''}>${s}</option>`).join('')}</select></div>`}
function renderTasks(){const list=state.tasks.filter(t=>(state.activeClient==='all'||t.clientId===state.activeClient)&&(state.taskFilter==='all'||t.status===state.taskFilter));return `<div class="workflow-steps"><span class="${state.taskFilter==='all'?'current':''}" data-filter="all"><i>1</i>All tasks</span>›<span data-filter="In Progress"><i>2</i>In progress</span>›<span data-filter="Waiting for Client"><i>3</i>Waiting</span>›<span data-filter="Completed"><i>4</i>Done</span></div><section class="workflow-panel"><div class="panel-head"><h2>${state.taskFilter==='all'?'Your tasks':state.taskFilter}</h2><span>${list.length} item${list.length===1?'':'s'} in this preview</span></div>${list.length?list.map(taskRow).join(''):`<div class="table-empty"><div class="empty-mini-icon">☷</div>No ${state.taskFilter==='all'?'tasks':state.taskFilter.toLowerCase()+' tasks'} yet.<br>Tasks you create will appear here.</div>`}</section><div class="soft-info"><b>Workflow:</b> New request → In progress → Waiting for client or approval → Scheduled → Completed. Update a status in the row to try it.</div>`}
function renderInbox(){const list=state.messages.filter(m=>state.activeClient==='all'||m.clientId===state.activeClient);return `<section class="workflow-panel"><div class="panel-head"><h2>Captured conversations</h2><span>${list.length} in this preview</span></div>${list.length?list.map(m=>`<article class="inbox-item"><span class="task-item-main"><b>${esc(m.text.slice(0,90))}${m.text.length>90?'…':''}</b><small>${clientMark(m.clientId)} ${esc(clientById(m.clientId)?.name||'Client')} · ${esc(m.channel)} · Just now</small></span><span class="task-status">Reviewed</span></article>`).join(''):`<div class="table-empty"><div class="empty-mini-icon">▤</div>Your inbox is empty.<br>Capture a conversation to see how it moves into your workspace.</div>`}</section><div class="soft-info"><b>Manual capture:</b> conversations are added only when you enter and confirm them. No messaging accounts are monitored.</div>`}
function renderCalendar(){const list=state.events.filter(e=>state.activeClient==='all'||e.clientId===state.activeClient);return `<section class="workflow-panel"><div class="panel-head"><h2>Appointments</h2><span>${list.length} in this preview</span></div>${list.length?list.map(e=>`<div class="task-item"><span class="task-item-main"><b>${esc(e.title)}</b><small>${clientMark(e.clientId)} ${esc(clientById(e.clientId)?.name||'Client')} · ${esc(e.date)} ${esc(e.time)}</small></span></div>`).join(''):`<div class="table-empty"><div class="empty-mini-icon">◷</div>No appointments on your calendar yet.<br>Create one to preview the client-linked calendar flow.</div>`}</section><div class="soft-info"><b>Internal calendar:</b> works without connecting an external calendar. Connections are not active in this demo.</div>`}
function renderClients(){return `<section class="workflow-panel"><div class="panel-head"><h2>Client workspaces</h2><span>${state.clients.length} in this preview</span></div>${state.clients.length?state.clients.map(c=>`<div class="task-item"><span class="context-dot" style="background:${c.color}"></span><span class="task-item-main"><b>${esc(c.name)}</b><small>${esc(c.email||'No email added')} · ${esc(c.channel)} · ${esc(c.timezone)}</small></span><button class="button button-secondary" data-action="select-client" data-client="${c.id}">Open workspace</button></div>`).join(''):`<div class="table-empty"><div class="empty-mini-icon">♙</div>No clients added yet.<br>Add a client to create their private workspace.</div>`}</section><div class="soft-info"><b>Separation by design:</b> each record belongs to one client. Your private notes remain assistant-only.</div>`}
function renderPortal(){const client=clientById(state.clients[0]?.id);const tasks=state.tasks.filter(t=>t.clientId===client?.id&&t.status!=='Completed');if(state.role==='employee'){app.innerHTML=`<div class="app-frame"><header class="workflow-header"><a class="workflow-brand" href="#" data-action="back-to-assistant"><span class="brand-glyph">f</span>fieldnote</a><div class="demo-indicator">EMPLOYEE PREVIEW · LIMITED VIEW</div><button class="role-switch" data-action="back-to-assistant">Back to assistant view</button></header><main class="workspace-main"><div class="main-heading"><div><div class="eyebrow">HOUSEHOLD TEAM</div><h1>Your day</h1><p>A simple view of your schedule and requests.</p></div></div><div class="employee-today"><b>Today’s shift</b><br>No shift is assigned in this preview. A real employee portal shows only your schedule, duties and requests.</div><h2 class="section-title">My schedule</h2><section class="workflow-panel"><div class="table-empty">No shifts scheduled.</div></section><h2 class="section-title">My requests</h2><section class="workflow-panel"><div class="table-empty">No leave or shift-change requests.</div></section><button class="button button-primary" data-action="leave-request">Request time off</button><div class="soft-info">This view does not include client contacts, invoices, expenses or assistant notes.</div></main></div>`;return}
app.innerHTML=`<div class="app-frame"><header class="workflow-header"><a class="workflow-brand" href="#" data-action="back-to-assistant"><span class="brand-glyph">f</span>fieldnote</a><div class="demo-indicator">CLIENT PREVIEW · SIMPLE AND PRIVATE</div><button class="role-switch" data-action="back-to-assistant">Back to assistant view</button></header><main class="workspace-main"><div class="role-view-banner"><strong>Client view</strong> · Only client-facing information appears here. Assistant notes and other clients are hidden.</div><section class="portal-card"><div class="portal-client-title"><div class="portal-avatar">${esc(initials(client?.name||'Client'))}</div><div><h2>${esc(client?.name||'Your client portal')}</h2><p>Your personal assistant’s updates</p></div></div><section class="portal-section"><h3>Needs your attention</h3>${tasks.filter(t=>t.status==='Waiting for Client'||t.status==='Waiting for Approval').map(t=>`<div class="portal-update"><span>${esc(t.title)}</span><span class="task-status">${esc(t.status)}</span></div>`).join('')||'<p>Nothing needs your attention right now.</p>'}</section><section class="portal-section"><h3>What is happening</h3>${tasks.map(t=>`<div class="portal-update"><span>${esc(t.title)}</span><span class="task-status">${esc(t.status)}</span></div>`).join('')||'<p>When your assistant starts work, updates will appear here.</p>'}</section><section class="portal-section"><h3>Coming up</h3><p>Your upcoming appointments will appear here.</p></section><section class="portal-section"><h3>Taken care of</h3><p>Completed work and shared updates will appear here.</p></section><section class="portal-section"><h3>Invoices and documents</h3><p>Shared invoices and documents will appear here when available.</p></section><button class="button button-primary" data-action="client-request">Send a request</button></section></main></div>`}
function showModal(html){state.modal=html;renderModal()}
function renderModal(){document.querySelector('.modal-backdrop')?.remove();if(!state.modal)return;document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true">${state.modal}</section></div>`)}
function clientForm(){return `<button class="modal-close" data-action="close-modal" aria-label="Close">×</button><h2>Add a client</h2><p>Create a separate workspace for someone you support.</p><form id="clientForm"><div class="form-field"><label for="addClientName">Client name</label><input class="input" id="addClientName" required placeholder="Full name"></div><div class="form-grid"><div class="form-field"><label for="addClientEmail">Email</label><input class="input" id="addClientEmail" type="email" placeholder="Optional"></div><div class="form-field"><label for="addClientPhone">Phone</label><input class="input" id="addClientPhone" placeholder="Optional"></div></div><div class="form-grid"><div class="form-field"><label for="addClientChannel">Preferred channel</label><select class="select" id="addClientChannel"><option>WhatsApp</option><option>iMessage</option><option>SMS</option><option>Email</option></select></div><div class="form-field"><label for="addClientCurrency">Currency</label><select class="select" id="addClientCurrency"><option>INR</option><option>USD</option><option>GBP</option><option>EUR</option></select></div></div><div class="soft-info">This client’s records stay separate. This preview does not send an invitation.</div><button class="button button-primary button-full">Create workspace</button></form>`}
function captureForm(){const clientOptions=state.clients.map(c=>`<option value="${c.id}" ${state.capture.clientId===c.id?'selected':''}>${esc(c.name)}</option>`).join('');return `<button class="modal-close" data-action="close-modal" aria-label="Close">×</button><div class="workflow-steps"><span class="${state.modalStep!=='review'?'current complete':''}"><i>1</i>Capture</span>›<span class="${state.modalStep==='review'?'current':''}"><i>2</i>Review</span>›<span><i>3</i>Create</span></div><h2>${state.modalStep==='review'?'Review the next step':'Capture a conversation'}</h2><p>${state.modalStep==='review'?'Edit the task details before adding it to the workspace.':'Enter a message manually. It will not be sent anywhere.'}</p>${state.modalStep==='review'?`<div class="review-card"><b>Message · ${esc(clientById(state.capture.clientId)?.name||'Client')} · ${esc(state.capture.channel)}</b><p>${esc(state.capture.text)}</p></div><form id="reviewForm"><div class="form-field"><label for="reviewTitle">Task title</label><input class="input" id="reviewTitle" required value="${esc(state.capture.taskTitle)}"></div><div class="form-grid"><div class="form-field"><label for="reviewDue">Due date</label><input class="input" id="reviewDue" type="date" value="${esc(state.capture.due)}"></div><div class="form-field"><label for="reviewPriority">Priority</label><select class="select" id="reviewPriority">${['Low','Normal','High','Urgent'].map(x=>`<option ${state.capture.priority===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="soft-info">Nothing has been added yet. Confirm to add the message and task to this browser session.</div><button class="button button-primary button-full">Confirm and add task</button><button class="button-text" type="button" data-action="edit-capture">← Edit message</button></form>`:`<form id="captureForm"><div class="capture-grid"><div class="form-field"><label for="captureClient">Client</label><select class="select" id="captureClient" required><option value="">Choose a client</option>${clientOptions}</select></div><div class="form-field"><label for="captureChannel">Channel</label><select class="select" id="captureChannel">${['WhatsApp','iMessage','SMS','Email','Phone','In person'].map(x=>`<option ${state.capture.channel===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field wide"><label for="captureText">What did they say?</label><textarea class="textarea" id="captureText" required placeholder="Type or paste the message…">${esc(state.capture.text)}</textarea></div><div class="form-field wide"><label for="capturePrivate">Private note <span class="optional">ONLY YOU CAN SEE THIS</span></label><textarea class="textarea" id="capturePrivate" placeholder="Add context for yourself…">${esc(state.capture.privateNote||'')}</textarea></div></div>${state.clients.length?'<button class="button button-primary button-full">Review next step</button>':'<div class="soft-info">Add a client first so this conversation is filed in the right private workspace.</div>'}</form>`}`}
function taskForm(){return `<button class="modal-close" data-action="close-modal" aria-label="Close">×</button><h2>Create a task</h2><p>Give the next step an owner, priority and due date.</p><form id="taskForm"><div class="form-field"><label for="taskName">Task name</label><input class="input" id="taskName" required placeholder="What needs to get done?"></div><div class="form-grid"><div class="form-field"><label for="taskClient">Client</label><select class="select" id="taskClient" required><option value="">Choose a client</option>${state.clients.map(c=>`<option value="${c.id}" ${state.activeClient===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="form-field"><label for="taskPriority">Priority</label><select class="select" id="taskPriority">${['Low','Normal','High','Urgent'].map(x=>`<option>${x}</option>`).join('')}</select></div></div><div class="form-field"><label for="taskDue">Due date <span class="optional">OPTIONAL</span></label><input class="input" id="taskDue" type="date"></div><div class="form-field"><label for="taskDetails">Details <span class="optional">OPTIONAL</span></label><textarea class="textarea" id="taskDetails" placeholder="Helpful context…"></textarea></div><button class="button button-primary button-full">Add task</button></form>`}
function eventForm(){return `<button class="modal-close" data-action="close-modal" aria-label="Close">×</button><h2>Add an appointment</h2><p>Plan an event in the internal calendar. Nothing syncs to an external account.</p><form id="eventForm"><div class="form-field"><label for="eventName">Event</label><input class="input" id="eventName" required placeholder="Appointment name"></div><div class="form-grid"><div class="form-field"><label for="eventClient">Client</label><select class="select" id="eventClient" required><option value="">Choose a client</option>${state.clients.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="form-field"><label for="eventDate">Date</label><input class="input" id="eventDate" type="date" required></div></div><div class="form-field"><label for="eventTime">Time</label><input class="input" id="eventTime" type="time" required></div><button class="button button-primary button-full">Add to calendar</button></form>`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){const a=b.dataset.action;if(a==='start'){state.screen='onboarding';state.step=1;render()}else if(a==='explore'){state.screen='workspace';render()}else if(a==='home'){e.preventDefault();state.screen='welcome';state.step=1;render()}else if(a==='profile-next'){const n=document.querySelector('#profileName');if(!n.value.trim()){n.focus();toast('Add your name to continue.');return}state.profile.name=n.value.trim();state.profile.email=document.querySelector('#profileEmail').value;state.profile.timezone=document.querySelector('#profileTimezone').value;state.step=2;render()}else if(a==='client-next'){const n=document.querySelector('#clientName');if(!n.value.trim()){n.focus();toast('Add a client name or choose Back to skip.');return}state.client.name=n.value.trim();state.client.email=document.querySelector('#clientEmail').value;state.client.phone=document.querySelector('#clientPhone').value;state.client.timezone=document.querySelector('#clientTimezone').value;state.client.currency=document.querySelector('#clientCurrency').value;state.client.channel=document.querySelector('#clientChannel').value;state.client.limit=document.querySelector('#clientLimit').value;state.step=3;render()}else if(a==='email-next'||a==='skip-email'){state.step=4;render()}else if(a==='back'){if(state.step>1){state.step--;render()}else{state.screen='welcome';render()}}else if(a==='enter-workspace'){enterWorkspace()}else if(a==='provider'){showModal(`<button class="modal-close" data-action="close-modal">×</button><div class="shield">✓</div><h2>Secure connection preview</h2><p>This is where ${esc(b.dataset.provider)}’s secure consent screen would open.</p><div class="consent-list"><span>Review email headers and message content for ${esc(state.client.name||'your client')}</span><span>Link selected email to tasks and events</span><span>Disconnect access from workspace settings</span></div><div class="soft-info"><b>No connection was made.</b> This preview does not contact ${esc(b.dataset.provider)} and never asks for an email password.</div><button class="button button-primary button-full" data-action="close-modal">Understood</button>`)}else if(a==='new-client'){showModal(clientForm())}else if(a==='capture'){state.modalStep='capture';state.capture={text:'',clientId:state.activeClient==='all'?(state.clients[0]?.id||''):state.activeClient,channel:'WhatsApp',taskTitle:'',due:'',priority:'Normal',privateNote:''};showModal(captureForm())}else if(a==='edit-capture'){state.modalStep='capture';state.capture.taskTitle=document.querySelector('#reviewTitle').value;state.capture.due=document.querySelector('#reviewDue').value;state.capture.priority=document.querySelector('#reviewPriority').value;showModal(captureForm())}else if(a==='new-task'){showModal(taskForm())}else if(a==='new-event'){if(!state.clients.length){toast('Add a client before creating an appointment.');return}showModal(eventForm())}else if(a==='close-modal'){state.modal='';document.querySelector('.modal-backdrop')?.remove()}else if(a==='select-client'){state.activeClient=b.dataset.client;state.view='dashboard';render()}else if(a==='portal'){state.role=b.dataset.role;state.screen='portal';render()}else if(a==='back-to-assistant'){state.role='assistant';state.screen='workspace';render()}else if(a==='client-request'){toast('In a connected portal, this opens a private request form.');}else if(a==='leave-request'){toast('In a connected portal, this opens a leave request form.');}return}
const view=e.target.closest('[data-view]');if(view){state.view=view.dataset.view;state.taskFilter='all';render();return}const filter=e.target.closest('[data-filter]');if(filter){state.taskFilter=filter.dataset.filter;render();return}});
document.addEventListener('change',e=>{if(e.target.id==='roleSwitch'){state.role=e.target.value;if(state.role==='assistant'){state.screen='workspace';render()}else{state.screen='portal';render()}}if(e.target.id==='clientSelect'){state.activeClient=e.target.value;render()}if(e.target.matches('[data-task-status]')){const task=state.tasks.find(t=>t.id===e.target.dataset.taskStatus);if(task){task.status=e.target.value;toast('Task updated to '+task.status);render()}}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='clientForm'){const nm=document.querySelector('#addClientName').value.trim();if(!nm)return;const id=crypto.randomUUID();state.clients.push({id,name:nm,email:document.querySelector('#addClientEmail').value,phone:document.querySelector('#addClientPhone').value,channel:document.querySelector('#addClientChannel').value,currency:document.querySelector('#addClientCurrency').value,timezone:'Asia/Kolkata',color:colors[state.clients.length%colors.length]});state.activeClient=id;state.modal='';state.view='dashboard';render();toast('Private workspace created for '+nm);return}
if(e.target.id==='captureForm'){state.capture.clientId=document.querySelector('#captureClient').value;state.capture.channel=document.querySelector('#captureChannel').value;state.capture.text=document.querySelector('#captureText').value.trim();state.capture.privateNote=document.querySelector('#capturePrivate').value.trim();if(!state.capture.clientId||!state.capture.text){toast('Choose a client and add the message.');return}const meaningful=state.capture.text.replace(/[“”"']/g,'').split(/\s+/).slice(0,8).join(' ');state.capture.taskTitle=meaningful.length>48?meaningful.slice(0,48)+'…':meaningful;state.modalStep='review';showModal(captureForm());return}
if(e.target.id==='reviewForm'){state.capture.taskTitle=document.querySelector('#reviewTitle').value.trim();state.capture.due=document.querySelector('#reviewDue').value;state.capture.priority=document.querySelector('#reviewPriority').value;const clientId=state.capture.clientId;state.messages.unshift({id:crypto.randomUUID(),clientId,text:state.capture.text,channel:state.capture.channel,privateNote:state.capture.privateNote});state.tasks.unshift({id:crypto.randomUUID(),clientId,title:state.capture.taskTitle,due:state.capture.due||'No due date',priority:state.capture.priority,status:'New Request',description:state.capture.text});state.modal='';state.view='tasks';state.activeClient=clientId;render();toast('Message reviewed and task added to this preview.');return}
if(e.target.id==='taskForm'){const clientId=document.querySelector('#taskClient').value;state.tasks.unshift({id:crypto.randomUUID(),clientId,title:document.querySelector('#taskName').value.trim(),due:document.querySelector('#taskDue').value||'No due date',priority:document.querySelector('#taskPriority').value,status:'New Request',description:document.querySelector('#taskDetails').value.trim()});state.activeClient=clientId;state.modal='';state.view='tasks';render();toast('Task added to this preview.');return}
if(e.target.id==='eventForm'){const clientId=document.querySelector('#eventClient').value;state.events.push({id:crypto.randomUUID(),clientId,title:document.querySelector('#eventName').value.trim(),date:document.querySelector('#eventDate').value,time:document.querySelector('#eventTime').value});state.activeClient=clientId;state.modal='';state.view='calendar';render();toast('Appointment added to this preview.')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal){state.modal='';document.querySelector('.modal-backdrop')?.remove()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();toast('Search can be connected when the workspace data source is added.')}});
// The sidebar modules and their workflows are session-only; no storage API is used.
Object.assign(state,{expenses:[],invoices:[],approvals:[],employees:[],documents:[],contacts:[],reminders:[],shifts:[],clockedIn:false,aiEnabled:false});
const moduleInfo={
 dashboard:['Dashboard','A calm overview of your work, with client boundaries always in view.','Create task','new-task'],inbox:['Inbox (Comms)','Review messages you have manually captured for each client.','Capture message','capture'],tasks:['Tasks','Move requests from first note to done, with a clear status at every step.','New task','new-task'],calendar:['Calendar','Plan client appointments in your internal calendar.','Add event','new-event'],email:['Email','Review email after a secure account connection, or manually capture an email thread.','Capture email','email-capture'],approvals:['Approvals','Record a decision request. The assistant should wait until the client approves.','Request approval','new-approval'],expenses:['Expenses','Record client-paid purchases or assistant-paid reimbursable expenses.','Add expense','new-expense'],invoices:['Invoices & Billing','Draft invoices and track payment status. No payment processing is connected.','Create invoice','new-invoice'],staff:['Household Staff','Add household team members, then assign duties and shifts.','Add staff member','new-employee'],documents:['Documents & Vault','Add a document reference to a client workspace. Files stay on this device in the preview.','Add document','new-document'],contacts:['Contacts Directory','Keep the useful people for each client in one place.','Add contact','new-contact'],reminders:['Reminders & Alerts','Set a reminder in this preview. Delivery to email or messaging apps is not connected.','Create reminder','new-reminder'],clients:['Client Workspaces','Create separate workspaces for every person you support.','Add client','new-client'],settings:['Integrations & Settings','Review secure connections, privacy controls and workspace settings.','View connections','integration-preview']
};
const moduleOrder=[['dashboard','▦','Dashboard'],['inbox','▱','Inbox (Comms)'],['tasks','☑','Tasks'],['calendar','▣','Calendar'],['email','✉','Email'],['approvals','♧','Approvals'],['expenses','＄','Expenses'],['invoices','▤','Invoices & Billing'],['staff','♙','Household Staff'],['documents','▧','Documents & Vault'],['contacts','♧','Contacts Directory'],['reminders','♧','Reminders & Alerts'],['clients','▣','Client Workspaces'],['settings','☷','Integrations & Settings']];
function renderWorkspace(){const c=clientById(state.activeClient)||state.clients[0],clientName=state.activeClient==='all'?(state.clients.length?'All clients':'No client selected'):c?.name||'No client selected',name=state.profile.name||'Assistant',meta=moduleInfo[state.view]||moduleInfo.dashboard;app.innerHTML=`<div class="app-frame"><header class="workflow-header"><a class="workflow-brand" href="#" data-action="home"><span class="brand-glyph">f</span>fieldnote</a><div class="demo-indicator"><i></i> Interactive preview · changes are temporary</div><div class="header-right"><select class="role-switch" id="roleSwitch" aria-label="Preview role"><option value="assistant">Assistant workspace</option><option value="client">Preview client portal</option><option value="employee">Preview employee portal</option></select><div class="user-pill"><span class="avatar">${esc(initials(name))}</span><span>${esc(name)}</span></div></div></header><div class="workspace-layout"><aside class="workspace-sidebar"><div class="workspace-name">ALL CLIENTS OVERVIEW <span>${state.clients.length} ACTIVE</span></div><div class="client-context">${clientMark(state.activeClient==='all'?'':c?.id||'')}<span>${esc(clientName)}</span><select class="client-context-select" id="clientSelect" aria-label="Select client"><option value="all" ${state.activeClient==='all'?'selected':''}>All clients</option>${state.clients.map(x=>`<option value="${x.id}" ${state.activeClient===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><nav class="side-nav module-nav" aria-label="Workspace modules">${moduleOrder.map(([id,icon,label])=>`<button data-view="${id}" class="${state.view===id?'active':''}"><span class="nav-glyph">${icon}</span><span>${label}</span>${id==='inbox'&&state.messages.length?`<span class="nav-badge">${state.messages.length}</span>`:''}${id==='tasks'&&state.tasks.length?`<span class="nav-badge">${state.tasks.length}</span>`:''}${id==='approvals'&&state.approvals.some(a=>a.status==='Pending')?`<span class="nav-badge">${state.approvals.filter(a=>a.status==='Pending').length}</span>`:''}</button>`).join('')}</nav><div class="side-divider"></div><div class="side-nav-label">PORTAL PREVIEWS</div><nav class="side-nav"><button data-action="portal" data-role="client"><span class="nav-glyph">◉</span><span>Client Portal</span></button><button data-action="portal" data-role="employee"><span class="nav-glyph">♙</span><span>Employee Portal</span></button></nav><div class="sidebar-note"><b>Private by design</b>Your client sees only shared work. Assistant notes and other client records stay private.</div></aside><main class="workspace-main"><div class="context-banner">${clientMark(state.activeClient==='all'?'':c?.id||'')}<span>Working in: <b>${esc(clientName)}</b></span><span class="private-icon">▣ Private workspace</span></div><div class="main-heading"><div><div class="eyebrow">${state.view==='dashboard'?'ALL CLIENTS OVERVIEW':'WORKSPACE'}</div><h1>${meta[0]}${state.view==='dashboard'&&state.profile.name?`, ${esc(name)}`:''}</h1><p>${meta[1]}</p></div><div class="heading-actions"><button class="button button-primary" data-action="${meta[3]}"><span>＋</span> ${meta[2]}</button></div></div>${renderCurrentView()}<footer class="workspace-footer"><span><i class="privacy-bullet"></i>Demo workspace · nothing is sent or saved</span><span>Refresh clears this preview</span></footer></main></div><nav class="mobile-bottom" aria-label="Workspace navigation"><button class="${state.view==='dashboard'?'active':''}" data-view="dashboard"><b>▦</b>Home</button><button class="${state.view==='inbox'?'active':''}" data-view="inbox"><b>▱</b>Inbox</button><button class="${state.view==='tasks'?'active':''}" data-view="tasks"><b>☑</b>Tasks</button><button class="${state.view==='calendar'?'active':''}" data-view="calendar"><b>▣</b>Calendar</button><button data-action="more-modules"><b>☷</b>More</button></nav></div>`}
function renderCurrentView(){switch(state.view){case'dashboard':return renderDashboard();case'inbox':return renderInbox();case'tasks':return renderTasks();case'calendar':return renderCalendar();case'clients':return renderClients();case'email':return renderEmail();case'approvals':return renderApprovals();case'expenses':return renderRecords('expenses');case'invoices':return renderRecords('invoices');case'staff':return renderStaff();case'documents':return renderRecords('documents');case'contacts':return renderRecords('contacts');case'reminders':return renderRecords('reminders');case'settings':return renderSettings();default:return renderDashboard()}}
function scoped(array){return array.filter(x=>state.activeClient==='all'||x.clientId===state.activeClient)}
function renderDashboard(){const tasks=scoped(state.tasks),open=tasks.filter(t=>t.status!=='Completed').length,wait=tasks.filter(t=>['Waiting for Client','Waiting for Approval'].includes(t.status)).length;return `<div class="metric-row"><div class="metric"><div class="metric-label">Client workspaces</div><div class="metric-value">${state.clients.length}</div><div class="metric-foot">Created by you</div></div><div class="metric"><div class="metric-label">Open tasks</div><div class="metric-value">${open}</div><div class="metric-foot">In this preview</div></div><div class="metric"><div class="metric-label">Waiting on a decision</div><div class="metric-value">${wait+state.approvals.filter(a=>a.status==='Pending').length}</div><div class="metric-foot">Requires follow-up</div></div><div class="metric"><div class="metric-label">Messages captured</div><div class="metric-value">${scoped(state.messages).length}</div><div class="metric-foot">Added by you</div></div></div><section class="empty-hero"><div class="empty-hero-copy"><div class="empty-hero-kicker">YOUR WORKSPACE, YOUR WAY</div><h2>${state.clients.length?'Every detail has a place.':'Start with one small thing.'}</h2><p>${state.clients.length?'Your clients, conversations and next steps are in one view. Add what you need and the workspace updates as you go.':'Nothing is prefilled here. Add your own client details, then try a message-to-task flow. All changes live only in this tab.'}<br><br><b>Nothing is saved or sent from this preview.</b></p><button class="button button-primary" data-action="${state.clients.length?'capture':'new-client'}">${state.clients.length?'Capture a conversation':'Add your first client'} <span class="button-arrow">→</span></button></div><div class="empty-art"><span class="floating-chip one">Client by client</span><span class="floating-chip two">Your notes stay private</span><div class="empty-art-center">f</div></div></section><div class="quick-action-row"><button data-action="capture">＋ Capture message</button><button data-action="new-task">＋ New task</button><button data-action="new-event">＋ Add event</button><button data-action="new-expense">＋ Add expense</button></div><h2 class="section-title">How work moves</h2><div class="workflow-cards"><article class="workflow-card"><span class="step-number">1</span><b>Capture a conversation</b><p>Choose a client and enter what they said.</p></article><article class="workflow-card"><span class="step-number">2</span><b>Review the next step</b><p>Edit a task before it is added to your list.</p></article><article class="workflow-card"><span class="step-number">3</span><b>Keep it moving</b><p>Update the status as work progresses.</p></article></div>${tasks.length?`<h2 class="section-title">Recent tasks</h2>${renderTaskPanel(tasks.slice(0,5))}`:''}`}
function moduleEmpty(title,desc,action,label){return `<div class="module-empty"><div class="empty-mini-icon">${({email:'✉',approvals:'✓',expenses:'＄',invoices:'▤',staff:'♙',documents:'▧',contacts:'♧',reminders:'♧',settings:'☷'})[state.view]||'＋'}</div><h3>${title}</h3><p>${desc}</p>${action?`<button class="button button-primary" data-action="${action}">＋ ${label}</button>`:''}</div>`}
function renderGenericRecords(key,items,columns,format){return `<section class="workflow-panel"><div class="panel-head"><h2>${columns.title}</h2><span>${items.length} added in this preview</span></div>${items.length?`<div class="records-list">${items.map(x=>format(x)).join('')}</div>`:moduleEmpty(columns.emptyTitle,columns.emptyDesc,columns.action,columns.actionLabel)}</section>`}
function recordLine(primary,secondary,status='',right=''){return `<div class="task-item"><span class="task-item-main"><b>${esc(primary)}</b><small>${secondary}</small></span>${status?`<span class="task-status">${esc(status)}</span>`:''}${right}</div>`}
function renderEmail(){const list=scoped(state.messages).filter(m=>m.channel==='Email');return `<div class="connection-banner"><span class="connection-icon">✉</span><div><b>Email connection preview</b><p>In the live product, connect a client's shared mailbox through secure provider consent. No password is stored.</p></div><button class="button button-secondary" data-action="integration-preview">Preview secure consent</button></div>${renderGenericRecords('messages',list,{title:'Email activity captured by you',emptyTitle:'No email captured',emptyDesc:'The email view is empty until you connect an account in the real product or capture an email conversation here.',action:'email-capture',actionLabel:'Capture an email'},m=>recordLine(m.text,`${clientMark(m.clientId)}${esc(clientById(m.clientId)?.name||'Client')} · ${esc(m.channel)} · Captured in this preview`,'Reviewed'))}<div class="soft-info"><b>Nothing syncs automatically.</b> This preview does not connect to Gmail, Outlook or Exchange.</div>`}
function renderApprovals(){return renderGenericRecords('approvals',scoped(state.approvals),{title:'Approval requests',emptyTitle:'No approvals waiting',emptyDesc:'Create a request when a purchase, booking or schedule change needs the client’s decision.',action:'new-approval',actionLabel:'Request approval'},a=>recordLine(a.title,`${clientMark(a.clientId)}${esc(clientById(a.clientId)?.name||'Client')} · ${esc(a.details||'Decision requested')}`,a.status,a.status==='Pending'?`<button class="button button-secondary" data-action="copy-approval" data-id="${a.id}">Client view</button>`:''))}
function renderRecords(view){const configs={expenses:{title:'Expenses',emptyTitle:'No expenses recorded',emptyDesc:'Add an expense to track the amount, payment type and client. Receipts are only referenced locally in this preview.',action:'new-expense',actionLabel:'Add expense'},invoices:{title:'Invoices',emptyTitle:'No invoices yet',emptyDesc:'Create a draft to see how billing details and status will appear.',action:'new-invoice',actionLabel:'Create invoice'},documents:{title:'Client documents',emptyTitle:'No documents added',emptyDesc:'Choose a local file to preview a document reference. The file is not uploaded or copied.',action:'new-document',actionLabel:'Add document'},contacts:{title:'Client contacts',emptyTitle:'No contacts yet',emptyDesc:'Add a vendor, school or other helpful contact to a client workspace.',action:'new-contact',actionLabel:'Add contact'},reminders:{title:'Reminders',emptyTitle:'No reminders set',emptyDesc:'Create a reminder to see it in your list. No message will be delivered.',action:'new-reminder',actionLabel:'Create reminder'}};const list=scoped(state[view]||[]);return renderGenericRecords(view,list,configs[view],x=>{if(view==='expenses')return recordLine(x.title,`${clientMark(x.clientId)}${esc(clientById(x.clientId)?.name||'Client')} · ${esc(x.category)} · ${esc(x.date||'No date')}`,x.status||x.kind,`${esc(x.currency)} ${esc(x.amount)}`);if(view==='invoices')return recordLine(x.title,`${clientMark(x.clientId)}${esc(clientById(x.clientId)?.name||'Client')} · Due ${esc(x.due||'not set')}`,x.status,`${esc(x.currency)} ${esc(x.amount)}`);if(view==='documents')return recordLine(x.title,`${clientMark(x.clientId)}${esc(clientById(x.clientId)?.name||'Client')} · ${esc(x.category)} · ${esc(x.filename)}`,'In this preview');if(view==='contacts')return recordLine(x.name,`${clientMark(x.clientId)}${esc(clientById(x.clientId)?.name||'Client')} · ${esc(x.role||'Contact')} · ${esc(x.phone||x.email||'No contact details')}`,'Contact');return recordLine(x.title,`${clientMark(x.clientId)}${esc(clientById(x.clientId)?.name||'Client')} · ${esc(x.when)} · ${esc(x.channel)} · Delivery is off`,'Scheduled',`<button class="button-text" data-action="complete-reminder" data-id="${x.id}">Mark done</button>`)})}
function renderApprovals(){return renderGenericRecords('approvals',scoped(state.approvals),{title:'Approvals',emptyTitle:'Nothing awaiting a decision',emptyDesc:'Create a request for a purchase, booking or schedule change. The client can review it in their portal preview.',action:'new-approval',actionLabel:'Request approval'},a=>recordLine(a.title,`${clientMark(a.clientId)}${esc(clientById(a.clientId)?.name||'Client')} · ${esc(a.details||'Decision requested')}${a.amount?` · ${esc(a.currency)} ${esc(a.amount)}`:''}`,a.status,a.status==='Pending'?`<button class="button button-secondary" data-action="open-approval-portal" data-client="${a.clientId}">Client view</button>`:''))}
function renderRecords(view){const cfg={expenses:['Expenses','No expenses recorded','Add a client expense or reimbursable purchase. Receipt names are only referenced locally.','new-expense','Add expense'],invoices:['Invoices & Billing','No invoices yet','Create a draft invoice to preview billing status and client context. Nothing is sent or paid.','new-invoice','Create invoice'],documents:['Documents & Vault','No documents added','Choose a local file and see its name associated with a client. File contents are not uploaded.','new-document','Add document'],contacts:['Contacts Directory','No contacts yet','Add a useful person and keep their details with the right client.','new-contact','Add contact'],reminders:['Reminders & Alerts','No reminders set','Create a reminder entry. No notification will be delivered.','new-reminder','Create reminder']}[view];const list=scoped(state[view]||[]);return renderGenericRecords(view,list,{title:cfg[0],emptyTitle:cfg[1],emptyDesc:cfg[2],action:cfg[3],actionLabel:cfg[4]},x=>{if(view==='invoices'){const suffix=`<select aria-label="Update invoice status" data-invoice-status="${x.id}">${['Draft','Sent','Paid','Partially Paid','Overdue','Cancelled'].map(s=>`<option ${s===x.status?'selected':''}>${s}</option>`).join('')}</select>`;return recordLine(x.title,`${clientMark(x.clientId)}${esc(clientById(x.clientId)?.name||'Client')} · Due ${esc(x.due||'not set')}`,`${x.status} · ${x.currency} ${x.amount}`,suffix)}if(view==='expenses')return recordLine(x.title,`${clientMark(x.clientId)}${esc(clientById(x.clientId)?.name||'Client')} · ${esc(x.category)} · ${esc(x.date||'No date')}`,x.status||x.kind,`${esc(x.currency)} ${esc(x.amount)}`);if(view==='documents')return recordLine(x.title,`${clientMark(x.clientId)}${esc(clientById(x.clientId)?.name||'Client')} · ${esc(x.category)} · ${esc(x.filename)}`,'Reference only');if(view==='contacts')return recordLine(x.name,`${clientMark(x.clientId)}${esc(clientById(x.clientId)?.name||'Client')} · ${esc(x.role||'Contact')} · ${esc(x.phone||x.email||'No contact details')}`,'Contact');return recordLine(x.title,`${clientMark(x.clientId)}${esc(clientById(x.clientId)?.name||'Client')} · ${esc(x.when)} · ${esc(x.channel)} · Not delivered`,'Scheduled',`<button class="button-text" data-action="complete-reminder" data-id="${x.id}">Mark done</button>`)})}
function renderStaff(){const rows=state.employees.map(x=>recordLine(x.name,`${esc(x.role)} · ${esc(x.phone||'No phone added')}`,'Team member'));const shifts=state.shifts.map(x=>recordLine(x.title,`${esc(x.date)} · ${esc(x.time)} · ${esc(x.employeeName)}`,'Shift'));return `<section class="workflow-panel"><div class="panel-head"><h2>Household team</h2><div class="panel-actions"><button class="button button-secondary" data-action="new-shift" ${!state.employees.length?'disabled':''}>＋ Add shift</button><button class="button button-primary" data-action="new-employee">＋ Add staff member</button></div></div>${rows.length?rows.join(''):moduleEmpty('No staff profiles yet','Add a household employee to begin. Payroll and payments are not part of this preview.','new-employee','Add staff member')}</section><h2 class="section-title">Schedule and duties</h2><section class="workflow-panel"><div class="panel-head"><h2>Upcoming shifts</h2><span>${state.shifts.length} added in this preview</span></div>${shifts.length?shifts.join(''):`<div class="table-empty">No shifts scheduled. Add a staff member first, then create a shift.</div>`}</section><div class="soft-info"><b>Payroll is not connected.</b> Attendance and shift requests are preview-only in this frontend.</div>`}
function renderSettings(){return `<section class="workflow-panel"><div class="panel-head"><h2>Integrations</h2><span>Secure connection previews</span></div>${[['Email','Google, Microsoft and Exchange'],['Calendar','Google, Outlook and Apple'],['Messaging','WhatsApp, SMS and iMessage']].map(([n,d])=>`<div class="task-item"><span class="task-item-main"><b>${n}</b><small>${d}</small></span><span class="task-status">Not connected</span><button class="button button-secondary" data-action="integration-preview">Review access</button></div>`).join('')}<div class="soft-info">These buttons show the planned consent flow only; no accounts are connected from this preview.</div></section><h2 class="section-title">Profile</h2><section class="workflow-panel"><form id="settingsForm" class="settings-form"><div class="form-grid"><div class="form-field"><label for="settingsName">Assistant name</label><input class="input" id="settingsName" value="${esc(state.profile.name)}"></div><div class="form-field"><label for="settingsTimezone">Time zone</label><select class="select" id="settingsTimezone">${timezones(state.profile.timezone)}</select></div></div><button class="button button-primary">Save for this preview</button></form></section><h2 class="section-title">Assistant suggestions</h2><section class="workflow-panel"><div class="task-item"><span class="task-item-main"><b>AI assistance</b><small>When enabled in a connected product, suggestions still need your review.</small></span><button class="button button-secondary" data-action="toggle-ai">${state.aiEnabled?'Turn off':'Turn on'} (preview)</button></div><div class="soft-info">No AI model is connected in this prototype, so no client content is processed.</div></section>`}
function moduleForm(kind){const head=`<button class="modal-close" data-action="close-modal" aria-label="Close">×</button>`;const clientSelect=`<div class="form-field"><label for="recordClient">Client</label><select class="select" id="recordClient" required><option value="">Choose a client</option>${state.clients.map(c=>`<option value="${c.id}" ${state.activeClient===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div>`;const field=(id,label,ph='',type='text',wide=false)=>`<div class="form-field ${wide?'wide':''}"><label for="${id}">${label}</label><input class="input" id="${id}" type="${type}" ${type==='number'?'min="0" step="0.01"':''} placeholder="${ph}" ${['recordTitle','recordAmount','recordName','recordDate','recordWhen','recordTime','recordDetails','recordFile'].includes(id)?'':''}></div>`;let title='',desc='',form='';switch(kind){case'expense':title='Add an expense';desc='Keep a clear record of client-paid or reimbursable spending.';form=`${clientSelect}<div class="form-grid">${field('recordTitle','What was purchased?','Vendor or item')}${field('recordAmount','Amount','0.00','number')}</div><div class="form-grid"><div class="form-field"><label for="recordCategory">Category</label><select class="select" id="recordCategory"><option>Travel</option><option>Household</option><option>Food</option><option>Supplies</option><option>Other</option></select></div><div class="form-field"><label for="recordKind">Payment type</label><select class="select" id="recordKind"><option>Client-paid</option><option>Assistant-paid reimbursable</option></select></div></div>${field('recordDate','Date','','date')}<div class="form-field"><label for="recordFile">Receipt reference <span class="optional">FILE NAME ONLY · NOT UPLOADED</span></label><input class="input" id="recordFile" type="file" accept="image/*,.pdf"></div><div class="soft-info">Card and bank details are never requested. This preview does not process payment.</div>`;break;
case'invoice':title='Create an invoice';desc='Start a draft invoice. Sending and payment processing are disabled in this preview.';form=`${clientSelect}${field('recordTitle','Invoice description','e.g. Assistant services')}${field('recordAmount','Amount','0.00','number')}<div class="form-grid">${field('recordDate','Invoice date','','date')}${field('recordDue','Due date','','date')}</div><div class="form-field"><label for="recordNotes">Notes</label><textarea class="textarea" id="recordNotes" placeholder="Optional details"></textarea></div><div class="soft-info">This creates a local draft only. No invoice is emailed and online payment is not available.</div>`;break;
case'approval':title='Request an approval';desc='Record what needs a decision. Do not proceed until approved.';form=`${clientSelect}<div class="form-field"><label for="recordTitle">What needs approval?</label><input class="input" id="recordTitle" required placeholder="Purchase, booking or schedule change"></div><div class="form-grid">${field('recordAmount','Amount','Optional','number')}<div class="form-field"><label for="recordDeadline">Decision by</label><input class="input" id="recordDeadline" type="date"></div></div><div class="form-field"><label for="recordDetails">Details for the client</label><textarea class="textarea" id="recordDetails" placeholder="Options, context and deadline"></textarea></div><div class="soft-info"><b>Approval gate:</b> wait for the client’s decision before confirming a purchase or booking.</div>`;break;
case'employee':title='Add household staff';desc='Create a basic profile for the employee schedule.';form=`${field('recordName','Employee name','Full name')}<div class="form-grid">${field('recordRole','Role','e.g. Driver')}${field('recordPhone','Phone','Optional','tel')}</div>${field('recordDetails','Duties','Optional details', 'text',true)}<div class="soft-info">This profile is only visible in your preview. No invite will be sent.</div>`;break;
case'shift':title='Add a shift';desc='Add a schedule entry to the employee preview.';form=`<div class="form-field"><label for="recordEmployee">Employee</label><select class="select" id="recordEmployee">${state.employees.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div>${field('recordTitle','Shift or duty','e.g. Morning school run')}${field('recordDate','Date','','date')}<div class="form-grid">${field('recordTime','Start time','','time')}${field('recordEnd','End time','','time')}</div>`;break;
case'document':title='Add a document reference';desc='Select a file to see its name in this preview. Its contents stay on your device.';form=`${clientSelect}<div class="form-field"><label for="recordCategory">Folder</label><select class="select" id="recordCategory"><option>Contracts</option><option>Insurance</option><option>Travel</option><option>Medical</option><option>Property</option><option>Receipts</option><option>Other</option></select></div><div class="form-field"><label for="recordFile">Choose a file</label><input class="input" id="recordFile" type="file"></div><div class="soft-info">The file will not be uploaded, copied or stored after refresh.</div>`;break;
case'contact':title='Add a contact';desc='Keep a useful person linked to the right client.';form=`${clientSelect}${field('recordName','Name','Full name')}<div class="form-grid">${field('recordRole','Category','e.g. School, vendor')}${field('recordPhone','Phone','Optional','tel')}</div>${field('recordEmail','Email','Optional','email')}`;break;
case'reminder':title='Create a reminder';desc='Create a local reminder entry. No message will be delivered.';form=`${clientSelect}${field('recordTitle','Reminder','What should you remember?')}<div class="form-grid">${field('recordDate','Date','','date')}${field('recordTime','Time','','time')}</div><div class="form-field"><label for="recordChannel">Preferred channel</label><select class="select" id="recordChannel"><option>In workspace</option><option>Email (not sent)</option><option>WhatsApp (not sent)</option><option>SMS (not sent)</option></select></div>`;break}
return `${head}<h2>${title}</h2><p>${desc}</p><form id="moduleForm" data-kind="${kind}"><div class="capture-grid">${form}</div><button class="button button-primary button-full">${kind==='invoice'?'Save draft':kind==='approval'?'Create approval request':kind==='shift'?'Add shift':kind==='document'?'Add reference':'Add to preview'}</button></form>`}
function showModuleForm(kind){if(['expense','invoice','approval','document','contact','reminder'].includes(kind)&&!state.clients.length){showModal(`<button class="modal-close" data-action="close-modal">×</button><h2>Add a client first</h2><p>This record needs a client workspace so it stays in the right place.</p><button class="button button-primary button-full" data-action="new-client">Add client</button>`);return}if(kind==='shift'&&!state.employees.length){toast('Add a staff member before scheduling a shift.');return}showModal(moduleForm(kind))}
function renderPortal(){const client=clientById(state.activeClient)||state.clients[0],clientTasks=state.tasks.filter(t=>t.clientId===client?.id),approvals=state.approvals.filter(a=>a.clientId===client?.id);if(state.role==='employee'){const list=state.shifts.map(x=>recordLine(x.title,`${esc(x.date)} · ${esc(x.time)} · ${esc(x.employeeName)}`,'Scheduled')).join('');app.innerHTML=`<div class="app-frame"><header class="workflow-header"><a class="workflow-brand" href="#" data-action="back-to-assistant"><span class="brand-glyph">f</span>fieldnote</a><div class="demo-indicator">EMPLOYEE PREVIEW · LIMITED VIEW</div><button class="role-switch" data-action="back-to-assistant">Back to assistant view</button></header><main class="workspace-main"><div class="role-view-banner"><strong>Employee view</strong> · This role sees only its schedule, duties and own requests.</div><div class="main-heading"><div><div class="eyebrow">HOUSEHOLD TEAM</div><h1>Your day</h1><p>Schedule and requests are empty until added in the assistant view.</p></div></div><div class="employee-today"><b>Attendance</b><br>${state.clockedIn?'You are clocked in for this preview.':'You are not clocked in.'}<br><button class="button button-primary" style="margin-top:10px" data-action="clock-toggle">${state.clockedIn?'Clock out':'Clock in'}</button></div><h2 class="section-title">My schedule</h2><section class="workflow-panel">${list||'<div class="table-empty">No shifts assigned.</div>'}</section><h2 class="section-title">Requests</h2><section class="workflow-panel">${state.requests.length?state.requests.map(r=>recordLine(r.title,`${esc(r.date)} · ${esc(r.note)}`,'Submitted')).join(''):'<div class="table-empty">No leave or shift-change requests.</div>'}</section><button class="button button-primary" data-action="leave-request">Request leave or a shift change</button><div class="soft-info">Expenses, invoices, client private information and assistant notes are hidden.</div></main></div>`;return}
app.innerHTML=`<div class="app-frame"><header class="workflow-header"><a class="workflow-brand" href="#" data-action="back-to-assistant"><span class="brand-glyph">f</span>fieldnote</a><div class="demo-indicator">CLIENT PREVIEW · SIMPLE AND PRIVATE</div><button class="role-switch" data-action="back-to-assistant">Back to assistant view</button></header><main class="workspace-main"><div class="role-view-banner"><strong>Client view</strong> · Only client-facing information appears here. Assistant notes and other clients are hidden.</div><section class="portal-card"><div class="portal-client-title"><div class="portal-avatar">${esc(initials(client?.name||'Client'))}</div><div><h2>${esc(client?.name||'Your client portal')}</h2><p>Updates from your personal assistant</p></div></div><section class="portal-section"><h3>Needs your attention</h3>${approvals.filter(a=>a.status==='Pending').map(a=>`<div class="approval-client-row"><div><b>${esc(a.title)}</b><small>${esc(a.details||'Approval requested')}${a.amount?` · ${esc(a.currency)} ${esc(a.amount)}`:''}</small></div><div class="approval-actions"><button class="button button-primary" data-action="decision" data-id="${a.id}" data-value="Approved">Approve</button><button class="button button-secondary" data-action="decision" data-id="${a.id}" data-value="Changes Requested">Request changes</button></div></div>`).join('')||'<p>Nothing needs your attention right now.</p>'}</section><section class="portal-section"><h3>What is happening</h3>${clientTasks.filter(t=>t.status!=='Completed').map(t=>`<div class="portal-update"><span>${esc(t.title)}</span><span class="task-status">${esc(t.status)}</span></div>`).join('')||'<p>When your assistant starts work, updates will appear here.</p>'}</section><section class="portal-section"><h3>Coming up</h3>${state.events.filter(x=>x.clientId===client?.id).map(x=>`<div class="portal-update"><span>${esc(x.title)}</span><span>${esc(x.date)} · ${esc(x.time)}</span></div>`).join('')||'<p>Your upcoming appointments will appear here.</p>'}</section><section class="portal-section"><h3>Taken care of</h3>${clientTasks.filter(t=>t.status==='Completed').map(t=>`<div class="portal-update"><span>${esc(t.title)}</span><span class="task-status done">Completed</span></div>`).join('')||'<p>Completed work and shared updates will appear here.</p>'}</section><section class="portal-section"><h3>Invoices and documents</h3><p>${[...state.invoices.filter(x=>x.clientId===client?.id),...state.documents.filter(x=>x.clientId===client?.id)].length?'Your shared items are available in this preview.':'Shared invoices and documents will appear here when available.'}</p></section><button class="button button-primary" data-action="client-request">Send a request</button></section></main></div>`}
function requestForm(){return `<button class="modal-close" data-action="close-modal">×</button><h2>Send a request</h2><p>In the live portal, this request goes to your assistant. This preview keeps it in the current tab.</p><form id="portalRequestForm"><div class="form-field"><label for="portalRequestTitle">What do you need?</label><input class="input" id="portalRequestTitle" required placeholder="Tell your assistant"></div><div class="form-field"><label for="portalRequestDate">When is it needed?</label><input class="input" id="portalRequestDate" type="date"></div><button class="button button-primary button-full">Add request to preview</button></form>`}
function leaveForm(){return `<button class="modal-close" data-action="close-modal">×</button><h2>Request time off or a shift change</h2><p>Your assistant can review this request in the staff workflow.</p><form id="leaveForm"><div class="form-field"><label for="leaveType">Request type</label><select class="select" id="leaveType"><option>Time off</option><option>Shift change</option></select></div><div class="form-field"><label for="leaveDate">Date</label><input class="input" id="leaveDate" type="date" required></div><div class="form-field"><label for="leaveNote">Note</label><textarea class="textarea" id="leaveNote" required placeholder="Add a short note"></textarea></div><button class="button button-primary button-full">Submit request</button></form>`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){const a=b.dataset.action;if(a==='more-modules'){showModal(`<button class="modal-close" data-action="close-modal">×</button><h2>Workspace sections</h2><p>Choose a module to explore.</p><div class="more-module-grid">${moduleOrder.filter(x=>x[0]!=='dashboard').map(([id,icon,label])=>`<button class="button button-secondary" data-view="${id}">${icon} ${label}</button>`).join('')}</div>`);return}if(a==='new-client'){showModal(clientForm());return}if(a==='new-expense'){showModuleForm('expense');return}if(a==='new-invoice'){showModuleForm('invoice');return}if(a==='new-approval'){showModuleForm('approval');return}if(a==='new-employee'){showModuleForm('employee');return}if(a==='new-shift'){showModuleForm('shift');return}if(a==='new-document'){showModuleForm('document');return}if(a==='new-contact'){showModuleForm('contact');return}if(a==='new-reminder'){showModuleForm('reminder');return}if(a==='email-capture'){state.capture.channel='Email';state.capture.clientId=state.activeClient==='all'?(state.clients[0]?.id||''):state.activeClient;state.modalStep='capture';state.capture.text='';showModal(captureForm());return}if(a==='integration-preview'){showModal(`<button class="modal-close" data-action="close-modal">×</button><h2>Secure connection preview</h2><p>This is a preview of the consent and permissions step.</p><div class="consent-list"><span>Connect only through the service provider’s secure sign-in</span><span>Review the requested permissions before connecting</span><span>Revoke or reconnect access from Integrations & Settings</span></div><div class="soft-info"><b>No connection was made.</b> This preview never collects a password or contacts an external service.</div><button class="button button-primary button-full" data-action="close-modal">Understood</button>`);return}if(a==='toggle-ai'){state.aiEnabled=!state.aiEnabled;render();toast(`AI suggestions ${state.aiEnabled?'enabled':'disabled'} for this preview.`);return}if(a==='complete-reminder'){const r=state.reminders.find(x=>x.id===b.dataset.id);if(r)r.status='Completed';render();toast('Reminder marked complete in this preview.');return}if(a==='copy-approval'){state.role='client';state.screen='portal';render();return}if(a==='decision'){const approval=state.approvals.find(x=>x.id===b.dataset.id);if(approval){approval.status=b.dataset.value;state.view='approvals';state.screen='workspace';render();toast(`Decision recorded: ${approval.status}`)}return}if(a==='clock-toggle'){state.clockedIn=!state.clockedIn;render();toast(state.clockedIn?'Clocked in for this preview':'Clocked out for this preview');return}if(a==='client-request'){showModal(requestForm());return}if(a==='leave-request'){showModal(leaveForm());return}}const v=e.target.closest('[data-view]');if(v&&moduleInfo[v.dataset.view]){state.modal='';document.querySelector('.modal-backdrop')?.remove();state.view=v.dataset.view;state.screen='workspace';render()}});
document.addEventListener('submit',e=>{if(e.target.id==='moduleForm'){e.preventDefault();const kind=e.target.dataset.kind,clientId=document.querySelector('#recordClient')?.value;const file=document.querySelector('#recordFile')?.files?.[0];const id=crypto.randomUUID();if(kind==='expense'){const amount=document.querySelector('#recordAmount').value;const c=clientById(clientId),over=Number(amount)>Number(c?.limit||Infinity);state.expenses.unshift({id,clientId,title:document.querySelector('#recordTitle').value.trim(),amount,currency:c?.currency||'INR',category:document.querySelector('#recordCategory').value,kind:document.querySelector('#recordKind').value,date:document.querySelector('#recordDate').value,receipt:file?.name||'',status:over?'Approval required':'Recorded'});if(over)state.approvals.unshift({id:crypto.randomUUID(),clientId,title:'Approve expense: '+document.querySelector('#recordTitle').value.trim(),amount,currency:c?.currency||'INR',details:'Over the client’s spending limit',status:'Pending'});state.view='expenses'}else if(kind==='invoice'){const c=clientById(clientId);state.invoices.unshift({id,clientId,title:document.querySelector('#recordTitle').value.trim(),amount:document.querySelector('#recordAmount').value,currency:c?.currency||'INR',date:document.querySelector('#recordDate').value,due:document.querySelector('#recordDue').value,status:'Draft'});state.view='invoices'}else if(kind==='approval'){const c=clientById(clientId);state.approvals.unshift({id,clientId,title:document.querySelector('#recordTitle').value.trim(),amount:document.querySelector('#recordAmount').value,currency:c?.currency||'INR',details:document.querySelector('#recordDetails').value.trim(),deadline:document.querySelector('#recordDeadline').value,status:'Pending'});state.view='approvals'}else if(kind==='employee'){state.employees.push({id,name:document.querySelector('#recordName').value.trim(),role:document.querySelector('#recordRole').value.trim(),phone:document.querySelector('#recordPhone').value.trim(),duties:document.querySelector('#recordDetails').value.trim()});state.view='staff'}else if(kind==='shift'){const emp=state.employees.find(x=>x.id===document.querySelector('#recordEmployee').value);state.shifts.push({id,employeeId:emp.id,employeeName:emp.name,title:document.querySelector('#recordTitle').value.trim(),date:document.querySelector('#recordDate').value,time:document.querySelector('#recordTime').value});state.view='staff'}else if(kind==='document'){state.documents.unshift({id,clientId,title:file?.name||'Document reference',filename:file?.name||'',category:document.querySelector('#recordCategory').value});state.view='documents'}else if(kind==='contact'){state.contacts.unshift({id,clientId,name:document.querySelector('#recordName').value.trim(),role:document.querySelector('#recordRole').value.trim(),phone:document.querySelector('#recordPhone').value.trim(),email:document.querySelector('#recordEmail').value.trim()});state.view='contacts'}else if(kind==='reminder'){state.reminders.unshift({id,clientId,title:document.querySelector('#recordTitle').value.trim(),when:`${document.querySelector('#recordDate').value} ${document.querySelector('#recordTime').value}`,channel:document.querySelector('#recordChannel').value,status:'Scheduled'});state.view='reminders'}state.activeClient=clientId||state.activeClient;state.modal='';render();toast(`${kind==='invoice'?'Draft invoice':kind==='approval'?'Approval request':kind==='employee'?'Staff profile':kind==='shift'?'Shift':kind==='document'?'Document reference':kind==='contact'?'Contact':kind==='reminder'?'Reminder':'Expense'} added to this preview.`)}
if(e.target.id==='settingsForm'){e.preventDefault();state.profile.name=document.querySelector('#settingsName').value.trim();state.profile.timezone=document.querySelector('#settingsTimezone').value;render();toast('Profile updated in this preview.')}});
render();
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='open-approval-portal'){state.activeClient=b.dataset.client;state.role='client';state.screen='portal';render()} });
document.addEventListener('change',e=>{if(e.target.matches('[data-invoice-status]')){const row=state.invoices.find(x=>x.id===e.target.dataset.invoiceStatus);if(row){row.status=e.target.value;toast('Invoice status updated in this preview.')}}});
document.addEventListener('submit',e=>{if(e.target.id==='portalRequestForm'){e.preventDefault();state.requests.push({title:document.querySelector('#portalRequestTitle').value.trim(),date:document.querySelector('#portalRequestDate').value||'Flexible',note:'Client request'});state.modal='';state.screen='portal';render();toast('Request added to this preview.');return}if(e.target.id==='leaveForm'){e.preventDefault();state.requests.push({title:document.querySelector('#leaveType').value,date:document.querySelector('#leaveDate').value,note:document.querySelector('#leaveNote').value.trim()});state.modal='';state.screen='portal';render();toast('Request submitted in this preview.')}});
function showModuleForm(kind){if(['expense','invoice','approval','document','contact','reminder'].includes(kind)&&!state.clients.length){showModal(`<button class="modal-close" data-action="close-modal">×</button><h2>Add a client first</h2><p>This record needs a client workspace so it stays in the right place.</p><button class="button button-primary button-full" data-action="new-client">Add client</button>`);return}if(kind==='shift'&&!state.employees.length){toast('Add a staff member before scheduling a shift.');return}showModal(moduleForm(kind));const required=kind==='expense'?['recordClient','recordTitle','recordAmount','recordDate']:kind==='invoice'?['recordClient','recordTitle','recordAmount']:kind==='approval'?['recordClient','recordTitle']:kind==='employee'?['recordName','recordRole']:kind==='shift'?['recordEmployee','recordTitle','recordDate','recordTime']:kind==='document'?['recordClient','recordFile']:kind==='contact'?['recordClient','recordName']:kind==='reminder'?['recordClient','recordTitle','recordDate']:[];required.forEach(id=>document.getElementById(id)?.setAttribute('required',''))}
const renderPortalWithoutRequests=renderPortal;
renderPortal=function(){renderPortalWithoutRequests();if(state.role!=='client')return;const card=app.querySelector('.portal-card');if(!card)return;card.querySelectorAll('.approval-actions button:nth-child(2)').forEach(button=>{button.dataset.value='Rejected';button.textContent='Reject'});const client=clientById(state.activeClient)||state.clients[0],requests=state.requests.filter(r=>!r.clientId||r.clientId===client?.id);if(requests.length){const section=document.createElement('section');section.className='portal-section';section.innerHTML=`<h3>Your requests</h3>${requests.map(r=>`<div class="portal-update"><span>${esc(r.title)}</span><span>${esc(r.date)}</span></div>`).join('')}`;card.insertBefore(section,card.querySelector(':scope > .button'))}};
document.addEventListener('submit',e=>{if(e.target.id==='portalRequestForm'){const request=state.requests.at(-1);if(request)request.clientId=state.activeClient==='all'?(state.clients[0]?.id||''):state.activeClient;render()}});
